import{_ as t,o,c as a,a5 as r}from"./chunks/framework.DbpUblpZ.js";const p=JSON.parse('{"title":"Simple formulas, room for custom models","description":"","frontmatter":{},"headers":[],"relativePath":"feature-deck.md","filePath":"feature-deck.md","lastUpdated":null}'),s={name:"feature-deck.md"};function i(n,e,c,l,d,m){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="Simple-formulas,-room-for-custom-models" tabindex="-1">Simple formulas, room for custom models <a class="header-anchor" href="#Simple-formulas,-room-for-custom-models" aria-label="Permalink to &quot;Simple formulas, room for custom models {#Simple-formulas,-room-for-custom-models}&quot;">​</a></h1><p>This deck shows how BayesianRegressionModels.jl combines concise regression formulas with custom model code. A population-PK example joins subject effects, a concentration calculation, and repeated measurements in one declaration. The larger examples show how this approach extends to more involved scientific models, with their current verification limits stated.</p><p>The deck also includes the corrected HSGP centering study and a possible future Julia-to-XLA path for GPU execution through Reactant. That path is a direction to investigate, not an existing BRM integration or a performance claim.</p><ul><li><p><a href="./decks/brm-futures.html">Open the self-contained RevealJS deck</a></p></li><li><p><a href="decks/brm-futures.pdf">Download the landscape PDF</a></p></li><li><p><a href="https://github.com/nsiccha/BayesianRegressionModels.jl/tree/ns/devibe/docs/presentations/brm-futures" target="_blank" rel="noreferrer">Inspect the deck source and references</a></p></li></ul><p>The main talk ends explicitly before a six-slide appendix covering execution support, the complete PK example, actual generated-code documentation, the centering study&#39;s source and evidence, and references. The displayed Julia examples are extracted from the executable feature atlas during rendering.</p><p>Prospective guests and cited authors have not reviewed or endorsed the deck.</p>',6)])])}const f=t(s,[["render",i]]);export{p as __pageData,f as default};
